SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT '2024-01-01'::date AS c0, (MAX ('epoch'::timestamptz) OVER () + '00:00:00.000001'::interval) AS c1 FROM tp AS a1 WHERE FALSE) AS ka UNION ALL SELECT 2 AS k FROM (SELECT AGE ((MAX ('1999-12-31 23:59:59.999999+05:30'::timestamptz) OVER (PARTITION BY 16) - '-1 month'::interval), DATE_TRUNC ('year', (SELECT MIN ('1999-12-31 23:59:59.999999+05:30'::timestamptz) FROM t4 AS a1))) AS c0, 45 AS c1, 40 AS c2) AS kb) AS u;
